<template><div class="page"><div class="page-header"><div><el-button link @click="router.back()"><ArrowLeft/>返回</el-button><h1 class="page-title">上传知识库</h1><p class="page-description">支持 PDF、DOCX、TXT 和 Markdown，单个文件不超过50MB。</p></div></div><div class="card card-body" style="max-width:880px"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="所属课程" prop="course"><el-select v-model="form.course" placeholder="请选择课程" style="width:100%"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="教学资料" prop="files"><el-upload ref="uploadRef" drag multiple :auto-upload="false" accept=".pdf,.docx,.txt,.md,.markdown" :on-change="change" :on-remove="change"><el-icon class="el-icon--upload"><UploadFilled/></el-icon><div class="el-upload__text">将文件拖到这里，或<em>点击选择文件</em></div><template #tip><div class="el-upload__tip">扫描版PDF无法提取文字，第一版暂不支持OCR。</div></template></el-upload></el-form-item><div class="form-grid"><el-form-item label="分块长度"><el-input-number v-model="form.chunk_size" :min="200" :max="4000" style="width:100%"/></el-form-item><el-form-item label="重叠长度"><el-input-number v-model="form.chunk_overlap" :min="0" :max="1000" style="width:100%"/></el-form-item><el-form-item><el-checkbox v-model="form.auto_chapter">自动识别章节</el-checkbox></el-form-item><el-form-item><el-checkbox v-model="form.auto_knowledge">自动提取知识点</el-checkbox></el-form-item></div><el-progress v-if="uploading" :percentage="progress"/><div class="result" v-if="results.length"><div v-for="r in results" :key="r.file"><StatusTag :value="r.status"/> {{r.file}} — {{r.message||'已加入队列'}}</div></div><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="uploading" @click="submit">上传并开始解析</el-button></el-form></div></div></template>
<script setup>import{reactive,ref,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{knowledgeApi}from'../../api';import{useAppStore}from'../../stores/app';import StatusTag from'../../components/StatusTag.vue';const route=useRoute(),router=useRouter(),store=useAppStore(),formRef=ref(),uploadRef=ref(),fileList=ref([]),uploading=ref(false),progress=ref(0),results=ref([]),form=reactive({course:route.query.course?Number(route.query.course):'',chunk_size:800,chunk_overlap:120,auto_chapter:true,auto_knowledge:true,files:[]}),rules={course:[{required:true,message:'请选择所属课程',trigger:'change'}],files:[{validator:(_,__,cb)=>fileList.value.length?cb():cb(new Error('至少选择一个文件')),trigger:'change'}]};const change=(_,list)=>{fileList.value=list;form.files=list};const submit=async()=>{await formRef.value.validate();if(form.chunk_overlap>=form.chunk_size)return ElMessage.warning('重叠长度必须小于分块长度');const data=new FormData();data.append('course',form.course);data.append('chunk_size',form.chunk_size);data.append('chunk_overlap',form.chunk_overlap);data.append('auto_chapter',form.auto_chapter);data.append('auto_knowledge',form.auto_knowledge);fileList.value.forEach(x=>data.append('files',x.raw));uploading.value=true;try{results.value=await knowledgeApi.upload(data,e=>progress.value=Math.round(e.loaded/e.total*100));ElMessage.success('上传完成，后台Worker正在处理')}finally{uploading.value=false}};onMounted(store.loadCourses)</script><style scoped>.el-upload{width:100%}.result{padding:14px;background:#f8fafc;border-radius:8px;margin:12px 0}.result>div{margin:6px 0}</style>
